    10→public static class BlobGasCalculator
    11→{
    12→    public static ulong CalculateBlobGas(int blobCount) =>
    13→        (ulong)blobCount * Eip4844Constants.GasPerBlob;
    14→
    15→    public static ulong CalculateBlobGas(Transaction transaction) =>
    16→        CalculateBlobGas(transaction.GetBlobCount());
    17→
    18→    public static ulong CalculateBlobGas(Transaction[] transactions)
    19→    {
    20→        int blobCount = 0;
    21→        foreach (Transaction tx in transactions)
    22→        {
    23→            if (tx.SupportsBlobs)
    24→            {
    25→                blobCount += tx.BlobVersionedHashes!.Length;
    26→            }
    27→        }
    28→
    29→        return CalculateBlobGas(blobCount);
    30→    }
    31→
    32→    public static bool TryCalculateBlobBaseFee(BlockHeader header, Transaction transaction, UInt256 blobGasPriceUpdateFraction, out UInt256 blobBaseFee)
    33→    {
    34→        if (!TryCalculateFeePerBlobGas(header.ExcessBlobGas.Value, blobGasPriceUpdateFraction, out UInt256 feePerBlobGas))
    35→        {
    36→            blobBaseFee = UInt256.MaxValue;
    37→            return false;
    38→        }
    39→        return !UInt256.MultiplyOverflow(CalculateBlobGas(transaction), feePerBlobGas, out blobBaseFee);
    40→    }
    41→
    42→    public static bool TryCalculateFeePerBlobGas(BlockHeader header, UInt256 blobGasPriceUpdateFraction, out UInt256 feePerBlobGas)
    43→    {
    44→        feePerBlobGas = UInt256.MaxValue;
    45→        return header.ExcessBlobGas is not null
    46→            && TryCalculateFeePerBlobGas(header.ExcessBlobGas.Value, blobGasPriceUpdateFraction, out feePerBlobGas);
    47→    }
    48→
    49→    public static bool TryCalculateFeePerBlobGas(ulong excessBlobGas, UInt256 blobGasPriceUpdateFraction, out UInt256 feePerBlobGas)
    50→    {
    51→        static bool FakeExponentialOverflow(UInt256 factor, UInt256 num, UInt256 denominator, out UInt256 feePerBlobGas)
    52→        {
